import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('lo-que-temi', 'C',
 [dict(t=587, e=655, titulo='Uno se vuelve atrayente de lo que teme', txt='Hoy les quiero hablar un poco acerca del temor, y me recordé de aquel versículo donde Job dice: «Lo que temía me ha sobrevenido». Nosotros tenemos que tener mucho cuidado con las cosas que nos dan miedo, con las cosas que nos dan temor, porque uno se vuelve atrayente de lo que a uno le da temor: como aquella persona que tiene mucho temor de que a sus hijos les vaya a pasar algo cuando salen a la calle a hacer sus cosas cotidianas, y precisamente les pasa algo. Por eso tenemos que trabajar en nuestra alma y entregarle a Dios todo temor.'),
  dict(t=2488, e=2545, titulo='Perfeccionados en el temor de Dios', txt='En el temor de Dios. No en el temor hacia la gente, no en el temor hacia un terremoto, no en el temor a una fiscalización, no en el temor a una deuda; póngale nombre. Sino que en el temor de Dios es que vamos siendo perfeccionados en la santidad. Entonces, aquella fidelidad hay que buscarla en todas las áreas de nuestra vida, porque alguien podría ser fiel no viendo cochinadas en las redes sociales, pero tal vez no diezma, y eso le hace infiel. Y podría ser alguien que ha guardado sus ojos y ha guardado sus diezmos y sus ofrendas, y es fiel en esas dos partes, pero tal vez llega tarde al trabajo […]'),
  dict(t=4407, e=4460, titulo='Persigue al Señor, no las riquezas', txt='No persigas las riquezas. Persigue al Señor. Busca primeramente el reino de Dios y su justicia, para que tú te vuelvas atrayente de todas las añadiduras del reino de los cielos, entre ellas las riquezas. Déjate bendecir por el Señor. Él no quiere la muerte del impío. Él te quiere restaurar. ¿Cómo te va a encontrar ese día el Señor? ¿Qué es lo último que te va a encontrar haciendo cuando se encuentre contigo? ¿Vas a confiar hoy en Dios?')],
 [dict(t=1877, txt='La primera es la venida secreta de nuestro Señor Jesucristo a recibir en las nubes a aquella con la que se va a casar, que es la iglesia escogida.'),
  dict(t=3128, txt='Se portó bien, se portó bien, resbaló y cayó, y luego buscó el rostro de Dios, y Dios lo restauró.'),
  dict(t=3754, txt='Cuando uno ya confía en el Señor, ya sabe cómo es Dios, y las cosas así se arreglan.')],
 ['¿Qué temor sigues dándole vueltas en tu mente y qué paso darías esta semana para entregárselo a Dios?',
  '¿En cuál de estos grupos te encuentras hoy —llamado, escogido o fiel— y qué área de tu vida falta consagrar?',
  'Cuando tu confianza en Dios se tambalea, ¿qué te ayuda a perseverar en lugar de retroceder?'],
 inicio=455)
